export function getRegionViewBox(regionCode?: string | null): string {
  if (!regionCode) return "0 0 800 800";
  const dromMap: Record<string, string> = {
    '971': '01',
    '972': '02',
    '973': '03',
    '974': '04',
    '976': '06',
  };
  const key = dromMap[regionCode] || regionCode;
  if (!REGION_BOUNDARIES[key]) return "0 0 800 800";
  return REGION_BOUNDARIES[key].viewBox;
}
